/* drag-lint 1.56 LIN-2 fixture schema: ORDERS reaches CUSTOMERS by one FK; ORDER_LINES is a child of ORDERS (no
   path ORDERS -> ORDER_LINES: the graph runs child -> parent). */
CREATE TABLE CUSTOMERS (ID INTEGER NOT NULL, NAME VARCHAR(40), DISCOUNT DOUBLE PRECISION,
  CONSTRAINT PK_CUSTOMERS PRIMARY KEY (ID));
CREATE TABLE ORDERS (ID INTEGER NOT NULL, CUST_ID INTEGER, QTY DOUBLE PRECISION, PRICE DOUBLE PRECISION,
  CONSTRAINT PK_ORDERS PRIMARY KEY (ID),
  CONSTRAINT FK_ORDERS_CUST FOREIGN KEY (CUST_ID) REFERENCES CUSTOMERS (ID));
CREATE TABLE ORDER_LINES (ID INTEGER NOT NULL, ORDER_ID INTEGER, AMOUNT DOUBLE PRECISION, QTY INTEGER,
  CONSTRAINT PK_ORDER_LINES PRIMARY KEY (ID),
  CONSTRAINT FK_LINES_ORDERS FOREIGN KEY (ORDER_ID) REFERENCES ORDERS (ID));
